1	import { create } from "zustand";
2	import { persist } from "zustand/middleware";
3	import type { Powertrain, BodyStyle, DrivetrainVariant } from "../types";
4	
5	export interface Filters {
6	  powertrain: Powertrain[] | "all";
7	  body_style: BodyStyle[] | "all";
8	  drivetrain: DrivetrainVariant[] | "all";
9	  max_price_cad: number | null;
10	  min_range_km: number | null;
11	  search: string;
12	}
13	
14	export type TouTier = "off_peak" | "mid_peak" | "on_peak";
15	
16	export const TOU_RATES: Record<TouTier, { label: string; rate: number }> = {
17	  off_peak: { label: "Off-peak (9.2 ¢/kWh)", rate: 0.092 },
18	  mid_peak: { label: "Mid-peak (13.6 ¢/kWh)", rate: 0.136 },
19	  on_peak: { label: "On-peak (17.9 ¢/kWh)", rate: 0.179 },
20	};
21	
22	interface AppState {
23	  // Filters & compare
24	  filters: Filters;
25	  compareIds: string[]; // max 4
26	  setFilter: <K extends keyof Filters>(key: K, value: Filters[K]) => void;
27	  resetFilters: () => void;
28	  toggleCompare: (id: string) => void;
29	  clearCompare: () => void;
30	
31	  // Thermal slider state
32	  temp_c: number; // -40..+40
33	  hvac_on: boolean;
34	  speed_kph: number;
35	  preconditioned: Record<string, boolean>; // vehicleId -> bool
36	  setTemp: (c: number) => void;
37	  setHvacOn: (v: boolean) => void;
38	  setSpeed: (v: number) => void;
39	  setPreconditioned: (id: string, v: boolean) => void;
40	  resetThermal: () => void;
41	
42	  // Electricity rate (Ontario TOU)
43	  touTier: TouTier;
44	  setTouTier: (tier: TouTier) => void;
45	
46	  // Plain / Geek display mode (mom mode)
47	  plainMode: boolean;
48	  setPlainMode: (v: boolean) => void;
49	}
50	
51	const DEFAULT_FILTERS: Filters = {
52	  powertrain: "all",
53	  body_style: "all",
54	  drivetrain: "all",
55	  max_price_cad: null,
56	  min_range_km: null,
57	  search: "",
58	};
59	
60	export const useAppStore = create<AppState>()(
61	  persist(
62	    (set) => ({
63	      filters: DEFAULT_FILTERS,
64	      compareIds: [],
65	      setFilter: (key, value) =>
66	        set((s) => ({ filters: { ...s.filters, [key]: value } })),
67	      resetFilters: () => set({ filters: DEFAULT_FILTERS }),
68	      toggleCompare: (id) =>
69	        set((s) => {
70	          if (s.compareIds.includes(id)) {
71	            return { compareIds: s.compareIds.filter((x) => x !== id) };
72	          }
73	          if (s.compareIds.length >= 4) return s;
74	          return { compareIds: [...s.compareIds, id] };
75	        }),
76	      clearCompare: () => set({ compareIds: [] }),
77	
78	      // Thermal defaults: 20 °C baseline, HVAC off, highway speed.
79	      temp_c: 20,
80	      hvac_on: false,
81	      speed_kph: 100,
82	      preconditioned: {},
83	      setTemp: (c) => set({ temp_c: Math.max(-40, Math.min(40, c)) }),
84	      setHvacOn: (v) => set({ hvac_on: v }),
85	      setSpeed: (v) => set({ speed_kph: Math.max(40, Math.min(130, v)) }),
86	      setPreconditioned: (id, v) =>
87	        set((s) => ({ preconditioned: { ...s.preconditioned, [id]: v } })),
88	      resetThermal: () =>
89	        set({ temp_c: 20, hvac_on: false, speed_kph: 100, preconditioned: {} }),
90	
91	      // Electricity rate — Ontario Hydro One TOU 2026, default mid-peak.
92	      touTier: "mid_peak",
93	      setTouTier: (tier) => set({ touTier: tier }),
94	
95	      // Plain / Geek display mode.
96	      plainMode: false,
97	      setPlainMode: (v) => set({ plainMode: v }),
98	    }),
99	    {
100	      name: "ev-store-v1",
101	      // Persist compare tray, filters, thermal settings, rate, and display mode — but not actions.
102	      partialize: (s) => ({
103	        compareIds: s.compareIds,
104	        filters: s.filters,
105	        temp_c: s.temp_c,
106	        hvac_on: s.hvac_on,
107	        speed_kph: s.speed_kph,
108	        touTier: s.touTier,
109	        plainMode: s.plainMode,
110	      }),
111	    },
112	  ),
113	);
